// source=components/site-nav.tsx
// component=SiteNav (.mt-nav-item)
import figma from 'figma'
const instance = figma.selectedInstance

// Nav items are generated by SiteNav from its PRIMARY list; this is the markup it renders.
const label = instance.getString('Label')
const current = instance.getEnum('State', {
  'Default': false,
  'Hover': false,
  'Selected': true,
  'Focus': false,
})
const icon = instance.getInstanceSwap('Icon')
let iconCode
if (icon && icon.type === 'INSTANCE') {
  iconCode = icon.executeTemplate().example
}

export default {
  example: figma.code`<a className="mt-nav-item" href={item.href}${current ? ' aria-current="page"' : ''}>${iconCode ? figma.code`${iconCode}` : ''}<span>${label}</span></a>`,
  id: 'mt-nav-item',
  metadata: { nestable: true },
}
